allApplicationStyleBlocks.declarations:
min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;

grid-template-columns: minmax(184px, 208px) minmax(0, 1fr);
  grid-template-areas:
    "directory bar"
    "directory editor";
  align-items: start;

display: flex;
  flex-wrap: wrap;
  position: static;
  top: auto;
  z-index: auto;
  gap: var(--tcrn-space-1);
  max-inline-size: 100%;
  overflow: visible;
